import{_ as s,o as t,c as o,l as r,t as a,N as n}from"./chunks/framework.Gjrf2Eoj.js";const y=JSON.parse('{"title":"shm_overview | x-cmd man (man7) | overview of POSIX shared memory","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | shm_overview - overview of POSIX shared memory","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"shm_overview | x-cmd man (man7) | overview of POSIX shared memory"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | shm_overview - overview of POSIX shared memory"}]]},"headers":[],"params":{"isMan":true,"man":"shm_overview","category":"man7","desc":"overview of POSIX shared memory"},"relativePath":"man7/shm_overview.md","filePath":"man7/shm_overview.md"}'),m={name:"man7/shm_overview.md"},i={class:"visually-hidden"},d=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>shm_overview - overview of POSIX shared memory</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The POSIX shared memory API allows processes to communicate information by sharing a region of memory.</p><p>The interfaces employed in the API are:</p><dl><dt><strong>shm_open</strong>(3)</dt><dd>Create and open a new object, or open an existing object. This is analogous to <strong>open</strong>(2). The call returns a file descriptor for use by the other interfaces listed below.</dd><dt><strong>ftruncate</strong>(2)</dt><dd>Set the size of the shared memory object. (A newly created shared memory object has a length of zero.)</dd><dt><strong>mmap</strong>(2)</dt><dd>Map the shared memory object into the virtual address space of the calling process.</dd><dt><strong>munmap</strong>(2)</dt><dd>Unmap the shared memory object from the virtual address space of the calling process.</dd><dt><strong>shm_unlink</strong>(3)</dt><dd>Remove a shared memory object name.</dd><dt><strong>close</strong>(2)</dt><dd>Close the file descriptor allocated by <strong>shm_open</strong>(3) when it is no longer needed.</dd><dt><strong>fstat</strong>(2)</dt><dd>Obtain a <em>stat</em> structure that describes the shared memory object. Among the information returned by this call are the object&#39;s size (<em>st_size</em>), permissions (<em>st_mode</em>), owner (<em>st_uid</em>), and group (<em>st_gid</em>).</dd><dt><strong>fchown</strong>(2)</dt><dd>To change the ownership of a shared memory object.</dd><dt><strong>fchmod</strong>(2)</dt><dd>To change the permissions of a shared memory object.</dd></dl><h3 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h3><p>POSIX shared memory is supported since Linux 2.4 and glibc 2.2.</p><h3 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h3><p>POSIX shared memory objects have kernel persistence: a shared memory object will exist until the system is shut down, or until all processes have unmapped the object and it has been deleted with <strong>shm_unlink</strong>(3)</p><h3 id="linking" tabindex="-1">Linking <a class="header-anchor" href="#linking" aria-label="Permalink to &quot;Linking&quot;">​</a></h3><p>Programs using the POSIX shared memory API must be compiled with <em>cc -lrt</em> to link against the real-time library, <em>librt</em>.</p><h3 id="accessing-shared-memory-objects-via-the-filesystem" tabindex="-1">Accessing shared memory objects via the filesystem <a class="header-anchor" href="#accessing-shared-memory-objects-via-the-filesystem" aria-label="Permalink to &quot;Accessing shared memory objects via the filesystem&quot;">​</a></h3><p>On Linux, shared memory objects are created in a (<strong>tmpfs</strong>(5)) virtual filesystem, normally mounted under <em>/dev/shm</em>. Since Linux 2.6.19, Linux supports the use of access control lists (ACLs) to control the permissions of objects in the virtual filesystem.</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Typically, processes must synchronize their access to a shared memory object, using, for example, POSIX semaphores.</p><p>System V shared memory (<strong>shmget</strong>(2), <strong>shmop</strong>(2), etc.) is an older shared memory API. POSIX shared memory provides a simpler, and better designed interface; on the other hand POSIX shared memory is somewhat less widely available (especially on older systems) than System V shared memory.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>fchmod</strong>(2), <strong>fchown</strong>(2), <strong>fstat</strong>(2), <strong>ftruncate</strong>(2), <strong>memfd_create</strong>(2), <strong>mmap</strong>(2), <strong>mprotect</strong>(2), <strong>munmap</strong>(2), <strong>shmget</strong>(2), <strong>shmop</strong>(2), <strong>shm_open</strong>(3), <strong>shm_unlink</strong>(3), <strong>sem_overview</strong>(7)</p>',19);function h(e,c,l,g,p,u){return t(),o("div",null,[r("h1",i,a(e.$params.man),1),d])}const v=s(m,[["render",h]]);export{y as __pageData,v as default};
